/*
 * A155557  A proximate-prime polynomial sequence generated by 2*n^2 - 2*n +
 *          53089.
 * https://oeis.org/A155557
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 2*n^2 - 2*n + 53089
 * Range:     u8 none, u16 n <= 79, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t nn = (seq_t)n;        /* convert index to seq_t for calculation */
    return 2 * nn * nn - 2 * nn + 53089;
}
